let checks = ref 0
let check value message = incr checks; if not value then failwith message
let reject code run =
  incr checks;
  match run () with
  | _ -> failwith ("Synthetic authority accepted invalid input; expected " ^ code)
  | exception Diagnostic.Error error -> if error.code <> code then
      failwith ("Expected " ^ code ^ ", got " ^ error.code ^ ": " ^ error.message)
let reject_message expected run =
  incr checks;
  match run () with
  | _ -> failwith "Synthetic constructor accepted invalid configuration"
  | exception Diagnostic.Error error ->
      if error.code <> "synthetic_authority" || error.message <> expected then
        failwith ("Constructor diagnostic order changed: " ^ error.code ^ ": " ^ error.message)
