let accepted = Json.array (get "accepted" literals)
let rejected = Json.array (get "rejected" literals)
let fixture name = List.find (fun value -> Json.string (get "name" value) = name) accepted
let raw name = get "expected" (fixture name)
let decode kind value =
  match kind with
  | "component" -> let item = C.of_json value in C.to_json item,C.fingerprint item,C.canonical_size item
  | "catalog" -> let item = K.of_json value in K.to_json item,K.fingerprint item,K.canonical_size item
  | "config" -> let item = G.of_json value in G.to_json item,G.fingerprint item,G.canonical_size item
  | "candidate" -> let item = A.of_json value in A.to_json item,A.fingerprint item,A.canonical_size item
  | kind -> failwith ("Unknown literal kind " ^ kind)
let copied kind value =
  match kind with
  | "component" ->
      let item = C.of_json value in
      let copy = C.make ~id:(C.id item) ~version:(C.version item) ~operation:(C.operation item)
        ~interface:(C.interface item) ~model_version:(C.model_version item) ~assumptions:(C.assumptions item)
        ~guarantees:(C.guarantees item) ~supported_profile:(C.supported_profile item) in C.to_json copy
  | "catalog" -> let item = K.of_json value in K.to_json (K.make ~version:(K.version item) (K.components item))
  | "config" ->
      let item = G.of_json value in
      G.to_json (G.make ~profile_version:(G.profile_version item) ~generator_version:(G.generator_version item)
        ~catalog_fingerprint:(G.catalog_fingerprint item) ~witness_selection:(G.witness_selection item)
        ~conjunction_strategy:(G.conjunction_strategy item) ())
  | "candidate" ->
      let item = A.of_json value in
      A.to_json (A.make ~request_fingerprint:(A.request_fingerprint item) ~mechanism:(A.mechanism item)
        ~observation_map:(A.observation_map item) ~source_map:(A.source_map item)
        ~behavior_requirement_ids:(A.behavior_requirement_ids item) ~component_locks:(A.component_locks item)
        ~generator_config:(A.generator_config item))
  | kind -> failwith ("Unknown literal kind " ^ kind)
let literals_and_catalogs () =
  check (List.length accepted = 22 && List.length rejected = 74) "Independent synthetic literal census changed";
  List.iter (fun value ->
    let name = Json.string (get "name" value) and kind = Json.string (get "kind" value) in
    let expected = get "expected" value in
    let result,fingerprint,size = decode kind (get "input" value) in
    check (Canonical.encode result = Canonical.encode expected) (name ^ ": full imported artifact changed");
    check (fingerprint = Json.string (get "fingerprint" value)) (name ^ ": independent identity changed");
    check (Z.of_int size = Json.integer (get "bytes" value)) (name ^ ": exact canonical byte size changed");
    check (Canonical.encode (copied kind result) = Canonical.encode expected) (name ^ ": constructor/accessor copy lost data")) accepted;
  List.iter (fun value ->
    let code = Json.string (get "native_code" value) and kind = Json.string (get "kind" value) in
    reject code (fun () -> decode kind (get "input" value))) rejected;
  List.iter (fun (catalog,name,count) ->
    check (Canonical.encode (K.to_json catalog) = Canonical.encode (raw name)) "Shipped catalog content differs from original Python";
    check (List.length (K.components catalog) = count) "Shipped catalog provider inventory changed";
    List.iter (fun component ->
      let found = Option.get (K.for_operation catalog (C.operation component)) in
      check (C.fingerprint found = C.fingerprint component) "Catalog lookup changed full provider identity") (K.components catalog);
    check (K.for_operation catalog "unknown" = None) "Catalog lookup invented an operation")
    [S.combinational_catalog,"combinational_catalog",9; S.temporal_catalog,"temporal_catalog",13];
  check (K.fingerprint (S.catalog_for_profile S.combinational_profile) = K.fingerprint S.combinational_catalog)
    "Combinational profile selected another catalog";
  check (K.fingerprint (S.catalog_for_profile S.temporal_profile) = K.fingerprint S.temporal_catalog)
    "Temporal profile selected another catalog";
  reject "synthetic_authority" (fun () -> S.catalog_for_profile "future");
  check (G.fingerprint (G.make ()) = Json.string (get "fingerprint" (fixture "combinational_native")))
    "Default generator configuration changed";
  check (G.fingerprint (G.make ~profile_version:S.temporal_profile ()) =
    Json.string (get "fingerprint" (fixture "temporal_native"))) "Temporal constructor failed to select its default catalog identity";
  reject_message "Unsupported synthetic generator version."
    (fun () -> G.make ~generator_version:"obsolete" ~catalog_fingerprint:"x" ());
  reject_message "The selected synthetic catalog is unavailable or stale."
    (fun () -> G.make ~catalog_fingerprint:"x" ~witness_selection:"future" ());
  reject_message "Unsupported response witness selection policy."
    (fun () -> G.make ~witness_selection:"future" ~conjunction_strategy:"future" ());
  check (S.catalog_version = K.version S.combinational_catalog &&
    S.generator_version = G.generator_version (G.make ()) &&
    S.model_runner_version = C.model_version (List.hd (K.components S.temporal_catalog)) &&
    S.checker_version = "biocompiler.synthetic.acceptance.v0.5") "Version authority changed";
  List.iter (fun name ->
    let candidate = A.of_json (raw name) in
    let catalog = S.catalog_for_profile (G.profile_version (A.generator_config candidate)) in
    let locks = K.lock catalog (A.mechanism candidate) in
    check (Canonical.encode (arr (List.map L.to_json locks)) =
      Canonical.encode (arr (List.map L.to_json (A.component_locks candidate))))
      (name ^ ": complete catalog lock identity or ordering changed"))
    ["base";"contact";"numeric";"negate";"held";"memory";"pulse";"event"];
  let temporal = A.of_json (raw "held") in
  reject "synthetic_catalog_operation" (fun () -> K.lock S.combinational_catalog (A.mechanism temporal))
let historical_scope () =
  let component = C.of_json (raw "custom_unicode_component") in
  check (C.operation component = "custom_operation" && C.supported_profile component = "arbitrary profile")
    "Imported records were narrowed to built-in operations/profiles";
  check (C.assumptions component = ["z";"a"]) "Ordered assumptions were sorted";
  let candidate = A.of_json (raw "unverified_claims_remain_importable") in
  check (List.for_all (fun (_,values) -> values = ["unknown_é";"z";"a"]) (A.source_map candidate))
    "Structural import silently checked or sorted source provenance";
  check (List.for_all (fun (_,values) -> values = []) (A.behavior_requirement_ids candidate))
    "Empty requirement correspondence was rejected despite complete node keys";
  check (Observation_map.inputs (A.observation_map candidate) = [] && Observation_map.outputs (A.observation_map candidate) = [])
    "Candidate import improperly required fresh contextual observation-map validity";
  check (List.for_all (fun lock -> L.component_id lock = "unavailable" && L.version lock = "9" &&
    L.content_fingerprint lock = String.make 64 'f') (A.component_locks candidate))
    "Candidate import silently refreshed stale locks";
  check (A.fingerprint (A.of_json (raw "numeric_representation_1")) <>
    A.fingerprint (A.of_json (raw "numeric_representation_1.0")))
    "Numerically equal integer/real declarations lost distinct canonical representation";
  let zero = raw "numeric_representation_-0.0" |> get "mechanism" |> get "nodes" |> Json.array |>
    List.find (fun node -> String.starts_with ~prefix:"active:" (Json.string (get "id" node))) in
  check (Canonical.encode (get "canonical_value" (get "value" (get "attributes" zero))) = "-0.0")
    "Signed real zero was normalized away";
  let base = A.of_json (raw "base") in
  let first,values = List.hd (A.source_map base) in
  let duplicate = (first,values) :: A.source_map base in
  reject "duplicate_key" (fun () -> A.make ~request_fingerprint:(A.request_fingerprint base)
    ~mechanism:(A.mechanism base) ~observation_map:(A.observation_map base) ~source_map:duplicate
    ~behavior_requirement_ids:(A.behavior_requirement_ids base) ~component_locks:(A.component_locks base)
    ~generator_config:(A.generator_config base));
  let changed = A.to_json base |> set "behavior_requirement_ids" (obj []) in
  reject "synthetic_authority" (fun () -> A.of_json changed);
  reject "synthetic_authority" (fun () -> A.of_json (set "source_map" (obj []) (A.to_json base)))
let boundaries () =
  let unicode = obj ["é😀\n",arr [Json.Float (-0.);Json.Int (Z.of_string "9007199254740993");str "\n\t\000"]] in
  let bytes,nodes = S.measure unicode in
  check (bytes = String.length (Canonical.encode unicode) && nodes = 6) "Canonical UTF-8 escape/key/value census differs";
  check (S.measure ~maximum:bytes unicode = (bytes,nodes)) "Exact byte boundary rejected";
  reject "synthetic_authority_limit" (fun () -> S.measure ~maximum:(bytes-1) unicode);
  let shared = arr [str "same";Json.Null] in
  let twice = arr [shared;shared] in
  check (S.measure twice = (String.length (Canonical.encode twice),7)) "Shared subtrees were deduplicated from resource census";
  let rec cyclic = Json.Array [cyclic] in
  reject "synthetic_authority_cycle" (fun () -> S.measure cyclic);
  let rec cyclic_values = Json.Null :: cyclic_values in
  reject "synthetic_authority_limit" (fun () -> S.measure (arr cyclic_values));
  let rec cyclic_fields = ("x",Json.Null) :: cyclic_fields in
  reject "synthetic_authority_limit" (fun () -> S.measure (obj cyclic_fields));
  reject "duplicate_key" (fun () -> S.measure (obj ["same",Json.Null;"same",Json.Null]));
  reject "nonfinite_number" (fun () -> S.measure (Json.Float infinity));
  let rec nested depth = if depth = 0 then Json.Null else arr [nested (depth-1)] in
  ignore (S.measure (nested Limits.max_depth));
  reject "synthetic_authority_limit" (fun () -> S.measure (nested (Limits.max_depth+1)));
  let exact_nodes = arr (List.init (Limits.max_json_nodes-1) (fun _ -> Json.Null)) in
  check (snd (S.measure exact_nodes) = Limits.max_json_nodes) "Exact aggregate node boundary rejected";
  reject "synthetic_authority_limit" (fun () -> S.measure (arr [exact_nodes]));
  let large = String.make Limits.max_string_bytes 'x' in
  ignore (S.measure (str large));
  reject "synthetic_authority_limit" (fun () -> S.measure (str (large ^ "x")));
  let exact = arr [str large;str large;str large;str (String.sub large 0 (String.length large-13))] in
  check (fst (S.measure exact) = Limits.max_request_bytes) "Exact 16 MiB aggregate boundary rejected";
  let oversized = arr [str large;str large;str large;str large] in
  reject "synthetic_authority_limit" (fun () -> S.measure oversized);
  let rec cyclic_names = "source" :: cyclic_names in
  reject "synthetic_authority_limit" (fun () -> C.make ~id:"bounded" ~version:"1" ~operation:"opaque" ~interface:"opaque"
    ~model_version:"1" ~assumptions:cyclic_names ~guarantees:[] ~supported_profile:"custom");
  let base = A.of_json (raw "base") in
  let make source_map = A.make ~request_fingerprint:(A.request_fingerprint base) ~mechanism:(A.mechanism base)
    ~observation_map:(A.observation_map base) ~source_map ~behavior_requirement_ids:(A.behavior_requirement_ids base)
    ~component_locks:(A.component_locks base) ~generator_config:(A.generator_config base) in
  let rec cyclic_map = ("source",["original"]) :: cyclic_map in
  reject "synthetic_authority_limit" (fun () -> make cyclic_map);
  reject "synthetic_authority_limit" (fun () -> make (List.map (fun (key,_) -> key,[large]) (A.source_map base)));
  let huge_component = C.make ~id:"huge" ~version:"1" ~operation:"opaque" ~interface:large ~model_version:"1"
    ~assumptions:[] ~guarantees:[] ~supported_profile:"custom" in
  (* Repeated instances are charged before semantic uniqueness is considered. *)
  reject "synthetic_authority_limit" (fun () -> K.make [huge_component;huge_component;huge_component;huge_component]);
  check (G.fingerprint (G.make ()) = Json.string (get "fingerprint" (fixture "combinational_native")))
    "Rejected oversized authority poisoned a later independent session"
let () =
  literals_and_catalogs ();
  historical_scope ();
  boundaries ();
  Printf.printf "synthetic authority: %d checks; 22 complete independent artifacts, 74 original Python rejections, both complete catalogs and bounded structural provenance\n" !checks

let () =
  (* Public order is observable in retained manager payloads, independently of
     canonical fingerprints. Imports may arrive in a different key order. *)
  let keys value = List.map fst (Json.object_fields value) in
  let imported = obj (List.rev (Json.object_fields (raw "base"))) in
  let candidate = A.of_json imported in
  let expected = ["schema_version";"intended_use";"human_therapeutic_admission";
    "request_fingerprint";"mechanism";"observation_map";"source_map";
    "behavior_requirement_ids";"component_locks";"generator_config"] in
  check (keys (A.to_json candidate) = expected) "Candidate import changed original public field order";
  check (keys (copied "candidate" imported) = expected) "Candidate constructor changed original public field order";
  check (A.fingerprint candidate = A.fingerprint (A.of_json (raw "base")))
    "Public candidate ordering changed canonical authority";
  let output = get "output" (List.hd (Json.array (get "nodes" (get "mechanism" (A.to_json candidate))))) in
  let observable = Measurement_contract.Observable.of_json (obj (List.rev (Json.object_fields output))) in
  check (keys (Measurement_contract.Observable.to_json observable) =
    ["schema_version";"id";"dtype";"role";"scope";"compartment"])
    "Observable type normalization moved the public dtype field"
